typedef struct exports_ffrwd_av_encoder_encoder_meta_t {
  // `meta.pixel-formats` or `meta.sample-formats` name the frames it
  // takes, most preferred first, the way a filter's do, and say its kind.
  exports_ffrwd_av_encoder_meta_t   meta;
  // The codec's name as a query, a message or a catalog spells it:
  // "pyrowave".
  codec_string_t   codec;
  // The four-character tag a container writes for it: "PYRW". Four
  // ASCII characters, exactly.
  codec_string_t   fourcc;
  // How many frames it takes in before its first packet leaves: 0 for an
  // intra-only codec that answers every frame in the call that brings it.
  uint32_t   delay;
  // How deep its packets reorder: how many packets a decoder holds back
  // before the first frame leaves it. 0 where decode order is
  // presentation order.
  uint32_t   decode_delay;
  // For audio, the samples every frame but the last must hold, which the
  // host cuts the stream into before it arrives; 0 takes a run of any
  // length. Always 0 for video.
  uint32_t   frame_samples;
} exports_ffrwd_av_encoder_encoder_meta_t;

